416	/* The NuttX arm_m layer looks up symbol "_vectors" and section ".vectors".
417	 * `used` prevents the compiler from dropping the table at LTO; `aligned(4)`
418	 * keeps each 4-byte slot naturally aligned.
419	 *
420	 * The table is sized explicitly at 80 entries (0x140 bytes) so the two
421	 * app-magic words at [64]/[65] are inside the table and the upper external
422	 * IRQ slots [66..79] are included.  After VTOR switches to RAM,
423	 * arm_ramvec_attach repairs slots 64/65 to exception_common.
424	 *
425	 * GCC range designated initializers fill the dispatcher slots the same way
426	 * arm_vectors.c does; the magic slots [64]/[65] are then pinned explicitly
427	 * (they are runtime-repaired after RAM vector init).
428	 */
429	
430	__attribute__((section(".vectors"), used, aligned(4)))
431	const void *const _vectors[80] =
432	{
433	  /* [0]    reset/IDLE stack top, preserved as PSP by the wrapper. */
434	  [0]  = (void *)BK7258_CP_IDLE_STACK,
435	
436	  /* [1]    reset wrapper; installs the dedicated interrupt MSP. */
437	  [1]  = (void *)bk7258_reset_entry,
438	
439	  /* [2..3] NMI + HardFault -> diagnostic bk7258_hardfault_handler.
440	   *   Capture the frame at 0x2809f100, print key registers on UART1, then
441	   *   park.  NMI ([2]) uses the same path so escalated faults are observable.
442	   */
443	  [2]  = &bk7258_hardfault_handler,
444	  [3]  = &bk7258_hardfault_handler,
445	
446	  /* [4..14] remaining system exceptions -> exception_common
447	   *   4=MemManage 5=BusFault 6=UsageFault 7=SecureFault 8..10=Reserved
448	   *   11=SVCall 12=DebugMonitor 13=Reserved 14=PendSV
449	   */
450	  [4 ... 14]  = &exception_common,
451	
452	  /* Route SysTick and lower external IRQs through the full context-saving
453	   * exception path.  SysTick is board-verified on this path; routing the
454	   * external slots the same way is the first UART RX IRQ recovery step. */
455	
456	  [15 ... 63] = &exception_common,
457	
458	  /* [64] app magic word 0: "BK72" little-endian.  Byte offset 0x100. */
459	  [64] = (void *)BK7258_APP_MAGIC_WORD0,
460	
461	  /* [65] app magic word 1: "36\0\0" little-endian. Byte offset 0x104. */
462	  [65] = (void *)BK7258_APP_MAGIC_WORD1,
463	
464	  /* [66..79] upper external IRQs -> exception_common
465	   *   These slots correspond to external IRQs 48..63.  Slots 64/65 are
466	   *   overwritten by the boot magic above and must be runtime-repaired
467	   *   via arm_ramvec_attach after VTOR switches to RAM.
468	   */
469	  [66 ... 79] = &exception_common
470	};
