170	static void os_timer_callback(wdparm_t arg)
171	{
172	  struct timer_adpt *timer_apt = (struct timer_adpt *)arg;
173	
174	  if (timer_apt->repeat)
175	    {
176	      beken_timer_t *timer = (beken_timer_t *)timer_apt->priv;
177	      if (timer->function)
178	        {
179	          timer->function(timer->arg);
180	        }
181	
182	      wd_start(&timer_apt->wdog, timer_apt->delay,
183	               os_timer_callback, arg);
184	    }
185	  else
186	    {
187	      beken2_timer_t *timer = (beken2_timer_t *)timer_apt->priv;
188	      if (timer->function)
189	        {
190	          timer->function(timer->left_arg, timer->right_arg);
191	        }
192	    }
193	}
