662	
663	bk_err_t rtos_init_queue(beken_queue_t *queue, const char *name,
664	                         uint32_t message_size,
665	                         uint32_t number_of_messages)
666	{
667	  struct mq_attr attr;
668	  struct mq_adpt_s *mq_adpt;
669	  int ret;
670	
671	  mq_adpt = kmm_malloc(sizeof(struct mq_adpt_s));
672	  if (!mq_adpt)
673	    {
674	      wlerr("ERROR: Failed to kmm_malloc\n");
675	      return BK_FAIL;
676	    }
677	
678	  memset(mq_adpt, 0x0, sizeof(struct mq_adpt_s));
679	
680	  if (name)
681	    {
682	      snprintf(mq_adpt->name, sizeof(mq_adpt->name), "/tmp/%s", name);
683	    }
684	  else
685	    {
686	      snprintf(mq_adpt->name, sizeof(mq_adpt->name), "/tmp/%p",
687	               mq_adpt);
688	    }
689	
690	  attr.mq_maxmsg  = number_of_messages;
691	  attr.mq_msgsize = message_size;
692	  attr.mq_curmsgs = 0;
693	  attr.mq_flags   = 0;
694	
695	  strncpy(mq_adpt->cname, name ? name : "null",
696	          sizeof(mq_adpt->cname) - 1);
697	
698	  ret = file_mq_open(&mq_adpt->mq, mq_adpt->name,
699	                     O_RDWR | O_CREAT, 0644, &attr);
700	  if (ret < 0)
701	    {
702	      wlerr("ERROR: Failed to create mqueue\n");
703	      kmm_free(mq_adpt);
704	      return beken_errno_trans(ret);
705	    }
706	
707	  mq_adpt->msgsize = message_size;
708	  *queue           = mq_adpt;
709	
710	  return beken_errno_trans(ret);
711	}
712	
713	bk_err_t rtos_push_to_queue(beken_queue_t *queue, void *message,
714	                            uint32_t timeout_ms)
715	{
716	  int ret;
717	  struct mq_adpt_s *mq_adpt = (struct mq_adpt_s *)*queue;
718	
719	  if (timeout_ms == BEKEN_WAIT_FOREVER || timeout_ms == 0)
720	    {
721	      ret = file_mq_send(&mq_adpt->mq, (const char *)message,
722	                         mq_adpt->msgsize, 0);
723	      if (ret < 0)
724	        {
725	          wlerr("Failed to send message to mqueue error=%d\n", ret);
726	        }
727	    }
728	  else
729	    {
730	      struct timespec timeout;
731	
732	      clock_gettime(CLOCK_REALTIME, &timeout);
733	      timeout.tv_sec  += timeout_ms / 1000;
734	      timeout.tv_nsec += (timeout_ms % 1000) * 1000 * 1000;
735	
736	      if (timeout.tv_nsec >= 1000000000)
737	        {
738	          timeout.tv_sec  += timeout.tv_nsec / 1000000000;
739	          timeout.tv_nsec %= 1000000000;
740	        }
741	
742	      ret = file_mq_timedsend(&mq_adpt->mq, (const char *)message,
743	                              mq_adpt->msgsize, 0, &timeout);
744	      if (ret < 0)
745	        {
746	          wlerr("Failed to timedsend message to mqueue error=%d\n", ret);
747	        }
748	    }
749	
750	  return beken_errno_trans(ret);
751	}
752	
753	bk_err_t rtos_push_to_queue_front(beken_queue_t *queue, void *message,
754	                                  uint32_t timeout_ms)
755	{
756	  /* NuttX mq does not support front insertion; fall back to normal send */
757	
758	  return rtos_push_to_queue(queue, message, timeout_ms);
759	}
760	
761	bk_err_t rtos_pop_from_queue(beken_queue_t *queue, void *message,
762	                             uint32_t timeout_ms)
763	{
764	  int ret;
765	  struct mq_adpt_s *mq_adpt = (struct mq_adpt_s *)*queue;
766	
767	  if (timeout_ms == BEKEN_WAIT_FOREVER)
768	    {
769	      ret = file_mq_receive(&mq_adpt->mq, message,
770	                            mq_adpt->msgsize, 0);
771	      if (ret < 0)
772	        {
773	          wlerr("Failed to receive message from mqueue error=%d\n", ret);
774	        }
775	    }
776	  else
777	    {
778	      struct timespec timeout;
779	
780	      clock_gettime(CLOCK_REALTIME, &timeout);
781	      timeout.tv_sec  += timeout_ms / 1000;
782	      timeout.tv_nsec += (timeout_ms % 1000) * 1000 * 1000;
783	
784	      if (timeout.tv_nsec >= 1000000000)
785	        {
786	          timeout.tv_sec  += timeout.tv_nsec / 1000000000;
787	          timeout.tv_nsec %= 1000000000;
788	        }
789	
790	      ret = file_mq_timedreceive(&mq_adpt->mq, message,
791	                                 mq_adpt->msgsize, 0, &timeout);
792	      if (ret < 0)
793	        {
794	          wlerr("Failed to timedreceive message from mqueue error=%d\n",
795	                ret);
796	        }
797	    }
798	
799	  return ret > 0 ? BK_OK : BK_FAIL;
800	}
