1612	
1613	  nxsem_destroy(sem);
1614	  kmm_free(sem);
1615	
1616	  return BK_OK;
1617	}
1618	
1619	bk_err_t rtos_set_event_ex(rtos_event_ext_t *event, u32 event_flag)
1620	{
1621	  sem_t *sem = (sem_t *)event->event_semaphore;
1622	
1623	  event->event_flag |= event_flag;
1624	  nxsem_post(sem);
1625	
1626	  return BK_OK;
1627	}
1628	
1629	u32 rtos_wait_event_ex(rtos_event_ext_t *event, u32 event_flag,
1630	                       u32 any_event, u32 timeout)
1631	{
1632	  sem_t *sem = (sem_t *)event->event_semaphore;
1633	  int ret;
1634	
1635	  if (timeout == BEKEN_WAIT_FOREVER)
1636	    {
1637	      ret = nxsem_wait(sem);
1638	    }
1639	  else if (timeout == 0)
1640	    {
1641	      ret = nxsem_trywait(sem);
1642	    }
1643	  else
1644	    {
1645	      ret = nxsem_tickwait(sem, MSEC2TICK(timeout));
1646	    }
1647	
1648	  if (ret == OK)
1649	    {
1650	      u32 flags = event->event_flag & event_flag;
1651	      event->event_flag &= ~event_flag;
1652	      return flags;
1653	    }
1654	
1655	  return 0;
1656	}
