53	/* The SDK read API consumes a byte, while the NuttX upper half separates
54	 * rxavailable() from receive().  Keep one byte of lookahead per port.
55	 */
56	
57	struct bk7258_uart_s
58	{
59	  uart_id_t id;
60	  int rxbyte;
61	};
62	
