34	  ((1u << BK7258_SDK_IRQ_PRIORITY_BITS) - 1u)
35	
36	#ifdef CONFIG_BK7258_GPIO_IRQ_TEST
37	#  define BK7258_SDK_IRQ_GPIO_SECURE_SOURCE \
38	  ((unsigned int)INT_SRC_GPIO)
39	#  define BK7258_SDK_IRQ_GPIO_NONSECURE_SOURCE  37u
40	#  define BK7258_SDK_IRQ_GPIO_SOURCE_COUNT      2u
41	#  define BK7258_SDK_IRQ_GPIO_SECURE_INDEX      0u
42	#  define BK7258_SDK_IRQ_GPIO_NONSECURE_INDEX   1u
43	#endif
44	
45	/****************************************************************************
46	 * Compile-time Invariants
47	 ****************************************************************************/
48	
49	_Static_assert(BK7258_SDK_IRQ_COUNT == 64,
50	               "Stage B gate: SDK IRQ source count must be 64");
51	_Static_assert(INT_SRC_NONE == BK7258_EXTERNAL_IRQS,
52	               "Stage B gate: SDK INT_SRC_NONE must follow source 63");
53	_Static_assert(BK7258_SDK_IRQ_FIRST + BK7258_SDK_IRQ_COUNT == NR_IRQS,
54	               "Stage B gate: SDK source 0..63 must map to IRQ 16..79");
55	_Static_assert(BK7258_SDK_IRQ_PRIORITY_BITS == 3,
56	               "Stage B gate: STAR NVIC implements three priority bits");
57	_Static_assert(INT_SRC_LCD == 27,
58	               "Stage B gate: LCD priority exception must remain source 27");
59	#ifdef CONFIG_BK7258_GPIO_IRQ_TEST
60	_Static_assert(INT_SRC_GPIO == 55,
61	               "GPIO IRQ test requires GPIO_S source 55");
62	_Static_assert(BK7258_SDK_IRQ_GPIO_NONSECURE_SOURCE == 37,
63	               "GPIO IRQ test requires GPIO_NS source 37");
64	#endif
65	_Static_assert(BK7258_SDK_IRQ_DEFAULT_PRIORITY <=
66	               BK7258_SDK_IRQ_PRIORITY_MAX,
67	               "Stage B gate: SDK default priority must be encodable");
68	_Static_assert(BK7258_SDK_IRQ_LCD_PRIORITY <=
69	               BK7258_SDK_IRQ_PRIORITY_MAX,
70	               "Stage B gate: SDK LCD priority must be encodable");
