109	static uint32_t bk7258_sdk_irq_default_priority(icu_int_src_t source)
110	{
111	  if (source == INT_SRC_LCD)
112	    {
113	      return BK7258_SDK_IRQ_LCD_PRIORITY;
114	    }
115	
116	  return BK7258_SDK_IRQ_DEFAULT_PRIORITY;
117	}
