119	static int bk7258_sdk_irq_dispatch(int irq, void *context, void *arg)
120	{
121	  unsigned int source;
122	  int_group_isr_t handler;
123	
124	  (void)context;
125	  (void)arg;
126	
127	  source = (unsigned int)(irq - BK7258_SDK_IRQ_FIRST);
128	  if (source >= BK7258_SDK_IRQ_COUNT)
129	    {
130	      return OK;
131	    }
132	
133	  handler = g_bk7258_sdk_irq_handlers[source];
134	
135	#ifdef CONFIG_BK7258_GPIO_IRQ_TEST
136	  if (source == BK7258_SDK_IRQ_GPIO_SECURE_SOURCE)
137	    {
138	      g_bk7258_sdk_irq_gpio_dispatch_counts[
139	        BK7258_SDK_IRQ_GPIO_SECURE_INDEX]++;
140	    }
141	  else if (source == BK7258_SDK_IRQ_GPIO_NONSECURE_SOURCE)
142	    {
143	      g_bk7258_sdk_irq_gpio_dispatch_counts[
144	        BK7258_SDK_IRQ_GPIO_NONSECURE_INDEX]++;
145	    }
146	#endif
147	
148	  if (handler != NULL)
149	    {
150	      handler();
151	    }
152	
153	  return OK;
154	}
