156	static bk_err_t
157	bk7258_sdk_irq_unregister_locked(unsigned int index, int irq)
158	{
159	  int ret;
160	
161	  up_disable_irq(irq);
162	  bk7258_clear_pending_irq(irq);
163	  g_bk7258_sdk_irq_handlers[index] = NULL;
164	  UP_DSB();
165	  UP_ISB();
166	
167	  ret = irq_detach(irq);
168	  return ret < 0 ? BK_FAIL : BK_OK;
169	}
