78	/* Read whole 4 KiB blocks.  SDK bk_flash_read_bytes handles alignment. */
79	
80	static ssize_t bk7258_flash_bread(FAR struct mtd_dev_s *dev, off_t startblock,
81	                                  size_t nblocks, FAR uint8_t *buffer)
82	{
83	  uint32_t offset = BK7258_DATA_PART_BASE +
84	                    (uint32_t)startblock * BK7258_FLASH_BLOCK_SIZE;
85	  uint32_t nbytes = (uint32_t)nblocks * BK7258_FLASH_BLOCK_SIZE;
86	
87	  (void)dev;
88	
89	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
90	    {
91	      return -EINVAL;
92	    }
93	
94	  if (bk_flash_read_bytes(offset, buffer, nbytes) != BK_OK)
95	    {
96	      return -EIO;
97	    }
98	
99	  return (ssize_t)nblocks;
100	}
101	
102	/* Erase whole 4 KiB sectors.  SDK handles SR0 protection internally
103	 * via bk_flash_set_protect_type. */
104	
105	static int bk7258_flash_erase(FAR struct mtd_dev_s *dev, off_t startblock,
106	                              size_t nblocks)
107	{
108	  size_t block;
109	
110	  (void)dev;
111	
112	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
113	    {
114	      return -EINVAL;
115	    }
116	
117	  bk_flash_set_protect_type(FLASH_PROTECT_NONE);
118	
119	  for (block = 0; block < nblocks; block++)
120	    {
121	      uint32_t addr = BK7258_DATA_PART_BASE +
122	                      ((size_t)startblock + block) * BK7258_FLASH_BLOCK_SIZE;
123	
124	      if (bk_flash_erase_sector(addr) != BK_OK)
125	        {
126	          bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
127	          return -EIO;
128	        }
129	    }
130	
131	  bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
132	  return OK;
133	}
134	
135	/* Write whole 4 KiB blocks.  SDK bk_flash_write_bytes handles 32-byte
136	 * page programming internally. */
137	
138	static ssize_t bk7258_flash_bwrite(FAR struct mtd_dev_s *dev, off_t startblock,
139	                                   size_t nblocks, FAR const uint8_t *buffer)
140	{
141	  uint32_t offset = BK7258_DATA_PART_BASE +
142	                    (uint32_t)startblock * BK7258_FLASH_BLOCK_SIZE;
143	  uint32_t nbytes = (uint32_t)nblocks * BK7258_FLASH_BLOCK_SIZE;
144	
145	  (void)dev;
146	
147	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
148	    {
149	      return -EINVAL;
150	    }
151	
152	  bk_flash_set_protect_type(FLASH_PROTECT_NONE);
153	
154	  if (bk_flash_write_bytes(offset, buffer, nbytes) != BK_OK)
155	    {
156	      bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
157	      return -EIO;
158	    }
159	
160	  bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
161	  return (ssize_t)nblocks;
162	}
