102	void bk7258_clock_bringup_320m(void)
103	{
104	  int tier;
105	
106	  /* Stepping the core clock to the 320 MHz runtime tier is the DVFS lower
107	   * half's job: it walks the SDK per-tier voltage/mux program one step at a
108	   * time (VDDD -> 0x7, VDDIG -> 0xD, then M1 cksel=2/clkdiv=0) and finally
109	   * recomputes the SysTick reload.  The DPLL was already enabled by the
110	   * bootloader's boot_clock.c cold-init (cold path) or is already running
111	   * (loader --reboot 1 residue on the soft path). */
