160	static int boot_cali_dpll(void)
161	{
162	    /* Lower the SPI trigger and settle. */
163	
164	    if (ana_and(ANA_REG0, ~(1u << 19)) < 0)   /* spitrig = 0 */
165	        return -1;
166	    clk_delay(120);
167	
168	    /* Rising edge starts recalibration; gate unlock-detect during settle. */
169	
170	    if (ana_rmw(ANA_REG0, (1u << 4), (1u << 19)) < 0)  /* spitrig=1, spideten=0 */
171	        return -1;
172	    clk_delay(3400);
173	
174	    /* Re-enable detect (the SDK's de-facto "lock wait"). */
175	
176	    if (ana_or(ANA_REG0, (1u << 4)) < 0)      /* spideten = 1 */
177	        return -1;
178	    clk_delay(3400);
179	
180	    return 0;
181	}
