191	
192	    uint32_t v = REG32(ANA_REG5);
193	    v &= ~(1u << 13);                              /* PWDAUDPLL = 0 */
194	    v |= (1u << 5) | (1u << 3) | (1u << 2);       /* EN_DPLL | NC_3_3 | EN_DCO */
