78	/* Read whole 4 KiB blocks.  SDK bk_flash_read_bytes handles alignment. */
79	
80	static ssize_t bk7258_flash_bread(FAR struct mtd_dev_s *dev, off_t startblock,
81	                                  size_t nblocks, FAR uint8_t *buffer)
82	{
83	  uint32_t offset = BK7258_DATA_PART_BASE +
84	                    (uint32_t)startblock * BK7258_FLASH_BLOCK_SIZE;
85	  uint32_t nbytes = (uint32_t)nblocks * BK7258_FLASH_BLOCK_SIZE;
86	
87	  (void)dev;
88	
89	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
90	    {
91	      return -EINVAL;
92	    }
93	
94	  if (bk_flash_read_bytes(offset, buffer, nbytes) != BK_OK)
95	    {
96	      return -EIO;
97	    }
98	
99	  return (ssize_t)nblocks;
100	}
