3311	  \brief   Enable I-Cache
3312	  \details Turns on I-Cache
3313	  */
3314	__STATIC_FORCEINLINE void SCB_EnableICache (void)
3315	{
3316	  #if defined (__ICACHE_PRESENT) && (__ICACHE_PRESENT == 1U)
3317	    if (SCB->CCR & SCB_CCR_IC_Msk) return;  /* return if ICache is already enabled */
3318	
3319	    __DSB();
3320	    __ISB();
3321	    SCB->ICIALLU = 0UL;                     /* invalidate I-Cache */
3322	    __DSB();
3323	    __ISB();
3324	    SCB->CCR |=  (uint32_t)SCB_CCR_IC_Msk;  /* enable I-Cache */
3325	    __DSB();
3326	    __ISB();
3327	  #endif
3328	}
