3364	/**
3365	  \brief   I-Cache Invalidate by address
3366	  \details Invalidates I-Cache for the given address.
3367	           I-Cache is invalidated starting from a 32 byte aligned address in 32 byte granularity.
3368	           I-Cache memory blocks which are part of given address + given size are invalidated.
3369	  \param[in]   addr    address
3370	  \param[in]   isize   size of memory block (in number of bytes)
3371	*/
3372	__STATIC_FORCEINLINE void SCB_InvalidateICache_by_Addr (void *addr, int32_t isize)
3373	{
3374	  #if defined (__ICACHE_PRESENT) && (__ICACHE_PRESENT == 1U)
3375	    if ( isize > 0 ) {
3376	       int32_t op_size = isize + (((uint32_t)addr) & (__SCB_ICACHE_LINE_SIZE - 1U));
3377	      uint32_t op_addr = (uint32_t)addr /* & ~(__SCB_ICACHE_LINE_SIZE - 1U) */;
3378	
3379	      __DSB();
3380	
3381	      do {
3382	        SCB->ICIMVAU = op_addr;             /* register accepts only 32byte aligned values, only bits 31..5 are valid */
3383	        op_addr += __SCB_ICACHE_LINE_SIZE;
3384	        op_size -= __SCB_ICACHE_LINE_SIZE;
3385	      } while ( op_size > 0 );
3386	
3387	      __DSB();
3388	      __ISB();
3389	    }
3390	  #endif
3391	}
