/* BK7258 STAR reports CONTROL as zero in Handler mode.  The generic NuttX
 * exception_common entry reads CONTROL after exception entry and therefore
 * stores zero in the outgoing task context.  On a later SVC switch that zero
 * is restored alongside an EXC_RETURN that requires PSP plus an active FP
 * context, and the return escalates as IACCVIOL.
 *
 * This flat build has one invariant Thread-mode CONTROL value for every task:
 * privileged, PSP selected, FP context active.  Patch both the context being
 * saved and the context selected by arm_doirq before exception_common restores
 * it.  Make.defs links this function through --wrap=arm_doirq on CPU0 only.
 */

extern uint32_t *__real_arm_doirq(int irq, uint32_t *regs);

uint32_t *__wrap_arm_doirq(int irq, uint32_t *regs)
{
  if (regs != NULL)
    {
      regs[REG_CONTROL] = CONTROL_SPSEL | CONTROL_FPCA;
    }

  regs = __real_arm_doirq(irq, regs);

  if (regs != NULL)
    {
      regs[REG_CONTROL] = CONTROL_SPSEL | CONTROL_FPCA;
    }

  return regs;
}

