177	  if (initialized)
178	    {
179	      return OK;
180	    }
181	
182	  if (bk_uart_driver_init() != BK_OK)
183	    {
184	      return -EIO;
185	    }
186	
187	  if (bk_uart_init(priv->id, &config) != BK_OK)
188	    {
189	      return -EIO;
190	    }
