319	static bool flash_is_need_update_status_reg(uint32_t protect_cfg, uint32_t cmp_cfg, uint32_t status_reg_val)
320	{
321		uint32_t cur_protect_val_in_status_reg = (status_reg_val >> s_flash.flash_cfg->protect_post) & s_flash.flash_cfg->protect_mask;
322		uint32_t cur_cmp_val_in_status_reg = (status_reg_val >> s_flash.flash_cfg->cmp_post) & FLASH_CMP_MASK;
323	
324		if (cur_protect_val_in_status_reg != protect_cfg ||
325			cur_cmp_val_in_status_reg != cmp_cfg) {
326			return true;
327		} else {
328			return false;
329		}
