332	static flash_protect_type_t flash_get_protect_type(uint32_t sr_value)
333	{
334		uint32_t type = 0;
335		uint16_t protect_value = 0;
336		uint16_t cmp;
337	
338		protect_value = sr_value >> s_flash.flash_cfg->protect_post;
339		protect_value = protect_value & s_flash.flash_cfg->protect_mask;
340	
341		cmp = (sr_value >> s_flash.flash_cfg->cmp_post) & FLASH_CMP_MASK;
342		protect_value |= cmp << FLASH_STATUS_REG_PROTECT_OFFSET;
343	
344		if (protect_value == s_flash.flash_cfg->protect_all)
345			type = FLASH_PROTECT_ALL;
346		else if (protect_value == s_flash.flash_cfg->protect_none)
347			type = FLASH_PROTECT_NONE;
348		else if (protect_value == s_flash.flash_cfg->unprotect_last_block)
349			type = FLASH_UNPROTECT_LAST_BLOCK;
350		else
351			type = FLASH_PROTECT_ALL;  // FLASH_UNPROTECT_LAST_BLOCK ???
352	
353		return type;
354	}
