356	static void flash_set_protect_type(flash_protect_type_t type)
357	{
358		uint32_t protect_cfg;
359		uint32_t cmp_cfg;
360		uint32_t status_reg = s_flash.flash_status_reg_val;
361	
362		protect_cfg = flash_get_protect_cfg(type);
363		cmp_cfg = flash_get_cmp_cfg(type);
364	
365		#if CONFIG_FLASH_SUPPORT_MULTI_PE  /* multiple process element. (multi-cores or SPE/NSPE) */
366		status_reg = flash_read_status_reg();
367		#endif
368	
369	#if CONFIG_FLASH_WRITE_STATUS_VOLATILE
370		flash_hal_set_volatile_status_write(&s_flash.hal);
371	#endif
372	
373		if (flash_is_need_update_status_reg(protect_cfg, cmp_cfg, status_reg)) {
374			flash_set_protect_cfg(&status_reg, protect_cfg);
375			flash_set_cmp_cfg(&status_reg, cmp_cfg);
376	
377			//FLASH_LOGV("write status reg:%x, status_reg_size:%d\r\n", status_reg, s_flash.flash_cfg->status_reg_size);
378			flash_write_status_reg(status_reg);
379		}
380	}
