382	static void flash_set_qe(void)
383	{
384		uint32_t status_reg = s_flash.flash_status_reg_val;
385	
386		#if CONFIG_FLASH_SUPPORT_MULTI_PE
387		status_reg = flash_read_status_reg();
388		#endif
389		if (((status_reg >> s_flash.flash_cfg->quad_en_post) & 0x01) == s_flash.flash_cfg->quad_en_val) {
390			return;
391		}
392	
393		if (1 == s_flash.flash_cfg->quad_en_val)
394			status_reg |= (1 << s_flash.flash_cfg->quad_en_post);
395		else
396			status_reg &= ~(1 << s_flash.flash_cfg->quad_en_post);
397	
398		flash_write_status_reg(status_reg);
399	}
