401	static void flash_read_common(uint8_t *buffer, uint32_t address, uint32_t len)
402	{
403		uint32_t addr = address & (~FLASH_ADDRESS_MASK);
404		uint32_t buf[FLASH_BUFFER_LEN] = {0};
405		uint8_t *pb = (uint8_t *)&buf[0];
406	
407		if (len == 0) {
408			return;
409		}
410	
411		while (len) {
412			uint32_t int_level = flash_enter_critical();
413	
414			flash_hal_set_op_cmd_read(&s_flash.hal, addr);
415			addr += FLASH_BYTES_CNT;
416			for (uint32_t i = 0; i < FLASH_BUFFER_LEN; i++) {
417				buf[i] = flash_hal_read_data(&s_flash.hal);
418			}
419			flash_exit_critical(int_level);
420	
421			for (uint32_t i = address % FLASH_BYTES_CNT; i < FLASH_BYTES_CNT; i++) {
422				*buffer++ = pb[i];
423				address++;
424				len--;
425				if (len == 0) {
426					break;
427				}
428			}
429		}
430	}
