465	static bk_err_t flash_write_common(const uint8_t *buffer, uint32_t address, uint32_t len)
466	{
467		uint32_t buf[FLASH_BUFFER_LEN];
468		uint8_t *pb = (uint8_t *)&buf[0];
469		uint32_t addr = address & (~FLASH_ADDRESS_MASK);
470	
471		FLASH_RETURN_ON_WRITE_ADDR_OUT_OF_RANGE(addr, len);
472	
473		while (len) {
474			os_memset(pb, 0xFF, FLASH_BYTES_CNT);
475			for (uint32_t i = address % FLASH_BYTES_CNT; i < FLASH_BYTES_CNT; i++) {
476				pb[i] = *buffer++;
477				address++;
478				len--;
479				if (len == 0) {
480					break;
481				}
482			}
483	
484			uint32_t int_level = flash_enter_critical();
485			flash_hal_wait_op_done(&s_flash.hal);
486	
487			for (uint32_t i = 0; i < FLASH_BUFFER_LEN; i++) {
488				flash_hal_write_data(&s_flash.hal, buf[i]);
489			}
490			flash_hal_set_op_cmd_write(&s_flash.hal, addr);
491			flash_exit_critical(int_level);
492	
493			addr += FLASH_BYTES_CNT;
494		}
495		return BK_OK;
496	}
