509	static flash_line_mode_t flash_set_line_mode(flash_line_mode_t line_mode)
510	{
511		uint32_t int_level = flash_enter_critical();
512	
513		flash_line_mode_t  new_line_mode;
514		flash_line_mode_t  old_line_mode = s_flash.flash_line_mode;
515	
516	#if CONFIG_FLASH_QUAD_ENABLE
517		if ( (FLASH_LINE_MODE_FOUR == line_mode)
518			&& (FLASH_LINE_MODE_FOUR == s_flash.flash_cfg->line_mode) )
519		{
520			new_line_mode = FLASH_LINE_MODE_FOUR;
521		}
522		else
523	#endif
524		{
525			new_line_mode = FLASH_LINE_MODE_TWO;
526		}
527	
528		if(new_line_mode == old_line_mode)
529		{
530			flash_exit_critical(int_level);
531			return old_line_mode;
532		}
533	
534		flash_hal_clear_qwfr(&s_flash.hal);   // cmd CRMR (coutinuous_read_mode reset), quit QPI mode.
535	
536	#if CONFIG_SOC_BK7236XX
537		sys_drv_set_sys2flsh_2wire(0);
538	#endif
539	
540		if (FLASH_LINE_MODE_FOUR == new_line_mode)
541		{
542			flash_hal_set_quad_m_value(&s_flash.hal, s_flash.flash_cfg->coutinuous_read_mode_bits_val);
543			flash_set_qe();
544			flash_hal_set_mode(&s_flash.hal, FLASH_MODE_QUAD);  // enter QPI mode.
545		}
546		else
547		{
548			flash_hal_set_mode(&s_flash.hal, FLASH_MODE_DUAL);
549		}
550	
551		s_flash.flash_line_mode = new_line_mode;
552	
553	#if CONFIG_SOC_BK7236XX
554		sys_drv_set_sys2flsh_2wire(1);
555	#endif
556	
557		flash_exit_critical(int_level);
558	
559		return old_line_mode;
560	
561	}
