162	static void flash_lock(void)
163	{
164		if(rtos_is_in_interrupt_context() || rtos_local_irq_disabled())
165		{
166	#if CONFIG_FLASH_CP_AP_DIRECT_ACCESS
167			uint32_t cpu_id = bk_flash_shared_get_cpu_id();
168			if (bk_flash_shared_acquire(cpu_id) != BK_OK)
169				BK_ASSERT(0);
170			s_flash_irq_lock_depth[cpu_id]++;
171	#endif
172			return;
173		}
174	
175	#ifdef CONFIG_FREERTOS_SMP
176		rtos_lock_mutex(&s_flash_mutex);
177	#endif
178	
179		vTaskSuspendAll();
180	
181	#if CONFIG_FLASH_CP_AP_DIRECT_ACCESS
182		s_flash_lock_cpu_id = bk_flash_shared_get_cpu_id();
183		if (bk_flash_shared_acquire(s_flash_lock_cpu_id) != BK_OK) {
184			s_flash_lock_cpu_id = FLASH_SHARED_CPU_MAX;
185			xTaskResumeAll();
186	#ifdef CONFIG_FREERTOS_SMP
187			rtos_unlock_mutex(&s_flash_mutex);
188	#endif
189			BK_ASSERT(0);
190		}
191	#endif
192	
193		mb_flash_op_prepare();
194	}
