196	static void flash_unlock(void)
197	{
198		if(rtos_is_in_interrupt_context() || rtos_local_irq_disabled())
199		{
200	#if CONFIG_FLASH_CP_AP_DIRECT_ACCESS
201			uint32_t cpu_id = bk_flash_shared_get_cpu_id();
202			if (s_flash_irq_lock_depth[cpu_id] > 0) {
203				s_flash_irq_lock_depth[cpu_id]--;
204				bk_flash_shared_release(cpu_id);
205			}
206	#endif
207			return;
208		}
209	
210		mb_flash_op_finish();
211	
212	#if CONFIG_FLASH_CP_AP_DIRECT_ACCESS
213		if (s_flash_lock_cpu_id < FLASH_SHARED_CPU_MAX) {
214			bk_flash_shared_release(s_flash_lock_cpu_id);
215			s_flash_lock_cpu_id = FLASH_SHARED_CPU_MAX;
216		}
217	#endif
218	
219		xTaskResumeAll();
220	
221	#ifdef CONFIG_FREERTOS_SMP
222		rtos_unlock_mutex(&s_flash_mutex);
223	#endif
224	}
