uint32_t rtos_disable_int(void)
{
  uint32_t int_level;

  /* The Armino SDK defines this pair as a raw PRIMASK save/restore, not an
   * RTOS scheduler critical section.  In particular, the flash driver uses
   * it while the XIP interface is servicing software commands.  BASEPRI
   * leaves NuttX SVC unmasked and can therefore start an exception return
   * whose first instruction fetch still targets unavailable XIP flash.
   */

  __asm volatile
    (
      "mrs %0, primask\n"
      "cpsid i\n"
      "dsb sy\n"
      "isb sy\n"
      : "=r" (int_level)
      :
      : "memory"
    );

  return int_level;
}

void rtos_enable_int(uint32_t int_level)
{
  __asm volatile
    (
      "dsb sy\n"
      "msr primask, %0\n"
      "isb sy\n"
      :
      : "r" (int_level)
      : "memory"
    );
}

