/* Interrupt stack in RAM (NuttX arm_getintstack.c references
 * g_intstackalloc / g_intstacktop).  Placed at the very start of RAM
 * so it has a fixed, predictable location.
 */
.irq_stack : ALIGN(4)
{
    g_intstackalloc = ABSOLUTE(.);
    . += CONFIG_ARCH_INTERRUPTSTACK;
    g_intstacktop = ABSOLUTE(.);
} > RAM

.ram_vectors (NOLOAD) : ALIGN(512)

/* Heap: from end of BSS up to the MSP region.  N1 never uses it but
 * the symbols must exist for the common ARM code to link.
 */
. = ALIGN(16);
_sheap = ABSOLUTE(.);
_eheap = ORIGIN(RAM) + LENGTH(RAM) - 4;

ASSERT(LOADADDR(.data) + SIZEOF(.data) <=
       ORIGIN(FLASH) + LENGTH(FLASH),
       "ERROR: CP load image overlaps LittleFS at logical 0x00100000")
ASSERT(_eheap < 0x28050000,
       "ERROR: CP RAM overlaps the AP RAM window")

input.new_string:
/* Reserve the handler MSP stack at the top of CP SRAM, matching the
 * vendor BK7236N/BK7258 layout.  Do not place it at 0x28000000: that
 * window aliases the STAR local TCM address zero, and the observed SVC
 * fault entered HardFault with MSP=0x70 and PC/LR=0xaaaaaaaa.
 *
 * Use board-private symbols because arm_exception.S also defines the
 * generic g_intstackalloc/g_intstacktop objects in .bss.  CPU0 wraps
 * up_get_intstackbase() so all NuttX stack initialization/coloring uses
 * this unambiguous reservation.
 */

. = ALIGN(16);
_sheap = ABSOLUTE(.);
_eheap = ORIGIN(RAM) + LENGTH(RAM) - CONFIG_ARCH_INTERRUPTSTACK;

.irq_stack
  (ORIGIN(RAM) + LENGTH(RAM) - CONFIG_ARCH_INTERRUPTSTACK) (NOLOAD) :
{
    . = ALIGN(8);
    _bk7258_intstack_base = ABSOLUTE(.);
    . += CONFIG_ARCH_INTERRUPTSTACK;
    _bk7258_intstack_top = ABSOLUTE(.);
} > RAM

ASSERT(_bk7258_intstack_top == ORIGIN(RAM) + LENGTH(RAM),
       "ERROR: CPU0 interrupt stack must end at the CP RAM boundary")
ASSERT(_ebss + CONFIG_IDLETHREAD_STACKSIZE <= _eheap,
       "ERROR: CPU0 data/IDLE stack overlaps the interrupt stack")
ASSERT(LOADADDR(.data) + SIZEOF(.data) <=
       ORIGIN(FLASH) + LENGTH(FLASH),
       "ERROR: CP load image overlaps LittleFS at logical 0x00100000")
ASSERT(_eheap < 0x28050000,
       "ERROR: CP RAM overlaps the AP RAM window")

