extern void __real_nxsched_resume_scheduler(struct tcb_s *tcb);

void __wrap_nxsched_resume_scheduler(struct tcb_s *tcb)
{
  if (g_bk7258_doirq_active != 0)
    {
      uint32_t *regs = tcb != NULL ? tcb->xcp.regs : NULL;

      /* With a dedicated interrupt stack, every Thread-mode context must use
       * PSP.  STAR reports CONTROL.SPSEL as zero in Handler mode, so the
       * generic save path otherwise stores zero and a later SysTick can run
       * the IDLE thread on the handler MSP.  Extended frames also require
       * CONTROL.FPCA to remain set.
