534	
535	/* The NuttX arm_m layer looks up symbol "_vectors" and section ".vectors".
536	 * `used` prevents the compiler from dropping the table at LTO; `aligned(4)`
537	 * keeps each 4-byte slot naturally aligned.
538	 *
539	 * The table is sized explicitly at 80 entries (0x140 bytes) so the two
540	 * app-magic words at [64]/[65] are inside the table and the upper external
541	 * IRQ slots [66..79] are included.  After VTOR switches to RAM,
542	 * arm_ramvec_attach repairs slots 64/65 to exception_common.
543	 *
544	 * GCC range designated initializers fill the dispatcher slots the same way
545	 * arm_vectors.c does; the magic slots [64]/[65] are then pinned explicitly
546	 * (they are runtime-repaired after RAM vector init).
547	 */
548	
549	__attribute__((section(".vectors"), used, aligned(4)))
550	const void *const _vectors[80] =
551	{
552	  /* [0]    reset/IDLE stack top, preserved as PSP by the wrapper. */
553	  [0]  = (void *)BK7258_CP_IDLE_STACK,
554	
555	  /* [1]    reset wrapper; installs the dedicated interrupt MSP. */
556	  [1]  = (void *)bk7258_reset_entry,
557	
558	  /* [2..3] NMI + HardFault -> diagnostic bk7258_hardfault_handler.
559	   *   Capture the frame at 0x2809f100, print key registers on UART1, then
560	   *   park.  NMI ([2]) uses the same path so escalated faults are observable.
561	   */
562	  [2]  = &bk7258_hardfault_handler,
563	  [3]  = &bk7258_hardfault_handler,
564	
565	  /* [4..14] remaining system exceptions -> exception_common
566	   *   4=MemManage 5=BusFault 6=UsageFault 7=SecureFault 8..10=Reserved
567	   *   11=SVCall 12=DebugMonitor 13=Reserved 14=PendSV
568	   */
569	  [4 ... 14]  = &exception_common,
570	
571	  /* Route SysTick and lower external IRQs through the full context-saving
572	   * exception path.  SysTick is board-verified on this path; routing the
573	   * external slots the same way is the first UART RX IRQ recovery step. */
574	
575	  [15 ... 63] = &exception_common,
576	
577	  /* [64] app magic word 0: "BK72" little-endian.  Byte offset 0x100. */
578	  [64] = (void *)BK7258_APP_MAGIC_WORD0,
579	
580	  /* [65] app magic word 1: "36\0\0" little-endian. Byte offset 0x104. */
581	  [65] = (void *)BK7258_APP_MAGIC_WORD1,
582	
583	  /* [66..79] upper external IRQs -> exception_common
584	   *   These slots correspond to external IRQs 48..63.  Slots 64/65 are
585	   *   overwritten by the boot magic above and must be runtime-repaired
586	   *   via arm_ramvec_attach after VTOR switches to RAM.
587	   */
588	  [66 ... 79] = &exception_common
589	};
