1	/****************************************************************************
2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/scripts/ld_ap.script
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * Linker script for the physical CPU1 / AP logical-core-0 NuttX image.
7	 *
8	 *   FLASH : 0x02200000 .. 0x023fffff  (logical offset 0x00200000)
9	 *   RAM   : 0x28050000 .. 0x2809efff
10	 *   SHARED: 0x2809f000 .. 0x2809ffff  (not linked into this image)
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	
15	OUTPUT_ARCH("arm")
16	EXTERN(_vectors)
17	EXTERN(__vector_core0_table)
18	EXTERN(bk7258_ap_main)
19	ENTRY(__start)
20	
21	MEMORY
22	{
23	    FLASH (rx)  : ORIGIN = 0x02200000, LENGTH = 0x200000
24	    RAM   (rwx) : ORIGIN = 0x28050000, LENGTH = 0x04f000
25	}
26	
27	_estack = ORIGIN(RAM) + LENGTH(RAM) - 4;
28	
29	SECTIONS
30	{
31	    . = ORIGIN(FLASH);
32	    .vectors : ALIGN(4)
33	    {
34	        KEEP(*(.vectors_core0))
35	        KEEP(*(.vectors))
36	        . = ALIGN(4);
37	    } > FLASH
38	
39	    ASSERT(__vector_core0_table == ORIGIN(FLASH),
40	           "ERROR: AP __vector_core0_table must be at 0x02200000")
41	    ASSERT(_vectors == __vector_core0_table,
42	           "ERROR: AP _vectors must alias __vector_core0_table")
43	    ASSERT(SIZEOF(.vectors) == 0x140,
44	           "ERROR: AP vector table must contain 80 entries")
45	
46	    .text : ALIGN(4)
47	    {
48	        _stext = ABSOLUTE(.);
49	        *(.text .text.*)
50	        *(.fixup)
51	        *(.gnu.warning)
52	        *(.rodata .rodata.*)
53	        *(.gnu.linkonce.t.*)
54	        *(.glue_7)
55	        *(.glue_7t)
56	        *(.gcc_except_table)
57	        *(.gnu.linkonce.r.*)
58	        . = ALIGN(4);
59	        _etext = ABSOLUTE(.);
60	    } > FLASH
61	
62	    .init_section : ALIGN(4)
63	    {
64	        _sinit = ABSOLUTE(.);
65	        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*)
66	               SORT_BY_INIT_PRIORITY(.ctors.*)))
67	        KEEP(*(.init_array
68	               EXCLUDE_FILE(*crtbegin.o *crtbegin?.o *crtend.o *crtend?.o)
69	               .ctors))
70	        _einit = ABSOLUTE(.);
71	    } > FLASH
72	
73	    .ARM.extab : ALIGN(4)
74	    {
75	        *(.ARM.extab*)
76	    } > FLASH
77	
78	    .ARM.exidx : ALIGN(4)
79	    {
80	        __exidx_start = ABSOLUTE(.);
81	        *(.ARM.exidx*)
82	        __exidx_end = ABSOLUTE(.);
83	    } > FLASH
84	
85	    .tdata : ALIGN(4)
86	    {
87	        _stdata = ABSOLUTE(.);
88	        *(.tdata .tdata.* .gnu.linkonce.td.*);
89	        _etdata = ABSOLUTE(.);
90	    } > FLASH
91	
92	    .tbss : ALIGN(4)
93	    {
94	        _stbss = ABSOLUTE(.);
95	        *(.tbss .tbss.* .gnu.linkonce.tb.* .tcommon);
96	        _etbss = ABSOLUTE(.);
97	    } > FLASH
98	
99	    _eronly = LOADADDR(.data);
100	
101	    .irq_stack : ALIGN(4)
102	    {
103	        g_intstackalloc = ABSOLUTE(.);
104	        . += CONFIG_ARCH_INTERRUPTSTACK;
105	        g_intstacktop = ABSOLUTE(.);
106	    } > RAM
107	
108	    .ram_vectors (NOLOAD) : ALIGN(512)
109	    {
110	        _sram_vectors = ABSOLUTE(.);
111	        KEEP(*(.ram_vectors))
112	        . = ALIGN(4);
113	        _eram_vectors = ABSOLUTE(.);
114	    } > RAM
115	
116	    ASSERT((_sram_vectors & 0x1ff) == 0,
117	           "ERROR: AP .ram_vectors must be 512-byte aligned")
118	    ASSERT(_eram_vectors - _sram_vectors == 0x140,
119	           "ERROR: AP .ram_vectors must contain 80 entries")
120	
121	    .data : ALIGN(4)
122	    {
123	        _sdata = ABSOLUTE(.);
124	        *(.data .data.*)
125	        *(.gnu.linkonce.d.*)
126	        CONSTRUCTORS
127	        . = ALIGN(4);
128	        _edata = ABSOLUTE(.);
129	    } > RAM AT > FLASH
130	
131	    .bss (NOLOAD) : ALIGN(4)
132	    {
133	        _sbss = ABSOLUTE(.);
134	        *(.bss .bss.*)
135	        *(.gnu.linkonce.b.*)
136	        *(COMMON)
137	        . = ALIGN(4);
138	        _ebss = ABSOLUTE(.);
139	    } > RAM
140	
141	    . = ALIGN(16);
142	    _sheap = ABSOLUTE(.);
143	    _eheap = ORIGIN(RAM) + LENGTH(RAM) - 4;
144	
145	    ASSERT(LOADADDR(.data) + SIZEOF(.data) <=
146	           ORIGIN(FLASH) + LENGTH(FLASH),
147	           "ERROR: AP image exceeds the app1 flash partition")
148	    ASSERT(_eheap < 0x2809f000,
149	           "ERROR: AP RAM overlaps the shared boot-state page")
150	
151	    .stab              0 : { *(.stab) }
152	    .stabstr           0 : { *(.stabstr) }
153	    .stab.excl         0 : { *(.stab.excl) }
154	    .stab.exclstr      0 : { *(.stab.exclstr) }
155	    .stab.index        0 : { *(.stab.index) }
156	    .stab.indexstr     0 : { *(.stab.indexstr) }
157	    .comment           0 : { *(.comment) }
158	    .debug_abbrev      0 : { *(.debug_abbrev) }
159	    .debug_info        0 : { *(.debug_info) }
160	    .debug_line        0 : { *(.debug_line) }
161	    .debug_pubnames    0 : { *(.debug_pubnames) }
162	    .debug_aranges     0 : { *(.debug_aranges) }
163	}
