47	static uint32_t apctl_u32(const char *value, uint32_t fallback)
48	{
49	  char *end;
50	  unsigned long parsed;
51	
52	  if (value == NULL)
53	    {
54	      return fallback;
55	    }
56	
57	  parsed = strtoul(value, &end, 0);
58	  if (*value == '\0' || *end != '\0' || parsed > UINT32_MAX)
59	    {
60	      return fallback;
61	    }
62	
63	  return (uint32_t)parsed;
64	}
65	
66	static void apctl_status(void)
67	{
68	  struct bk7258_ap_boot_state_s state;
69	
70	  bk7258_ap_get_status(&state);
71	  printf("AP state=%s(%" PRIu32 ") error=%" PRIu32
72	         " generation=%" PRIu32 " heartbeat=%" PRIu32 "\n",
73	         apctl_state_name(state.state), state.state, state.error,
74	         state.generation, state.heartbeat);
75	  printf("AP core local=%" PRIu32 " physical=%" PRIu32
76	         " VTOR(init/run)=%08" PRIx32 "/%08" PRIx32
77	         " MSP(init/run)=%08" PRIx32 "/%08" PRIx32 "\n",
78	         state.local_core_id, state.physical_core_id,
79	         state.initial_vtor, state.runtime_vtor,
80	         state.initial_msp, state.runtime_msp);
81	  printf("AP clock=%" PRIu32 " SysTick ctrl/load/current=%08" PRIx32
82	         "/%08" PRIx32 "/%08" PRIx32 "\n",
83	         state.clock_hz, state.systick_ctrl,
84	         state.systick_reload, state.systick_current);
85	  printf("AP heap=%08" PRIx32 "..%08" PRIx32
86	         " test=%08" PRIx32 " doorbells cp/ap=%" PRIu32 "/%" PRIu32
87	         "\n", state.heap_start, state.heap_end, state.heap_test,
88	         state.cp_to_ap_doorbells, state.ap_to_cp_doorbells);
89	}
90	
91	static void apctl_usage(void)
92	{
93	  printf("usage: apctl start|stop|restart|status [timeout_ms]\n");
94	  printf("       apctl cycle [count] [timeout_ms]\n");
95	}
96	
97	/****************************************************************************
98	 * Public Functions
99	 ****************************************************************************/
100	
101	int main(int argc, char *argv[])
102	{
103	  uint32_t timeout;
104	  uint32_t count;
105	  uint32_t i;
106	  int ret = -EINVAL;
107	
108	  if (argc < 2)
109	    {
110	      apctl_usage();
111	      return 1;
112	    }
113	
114	  timeout = apctl_u32(argc > 2 ? argv[2] : NULL,
115	                      BK7258_AP_DEFAULT_TIMEOUT_MS);
116	
117	  if (strcmp(argv[1], "start") == 0)
118	    {
119	      ret = bk7258_ap_start(timeout);
120	    }
121	  else if (strcmp(argv[1], "stop") == 0)
122	    {
123	      ret = bk7258_ap_stop(timeout);
124	    }
125	  else if (strcmp(argv[1], "restart") == 0)
126	    {
127	      ret = bk7258_ap_restart(timeout);
128	    }
129	  else if (strcmp(argv[1], "status") == 0)
130	    {
131	      apctl_status();
132	      return 0;
133	    }
134	  else if (strcmp(argv[1], "cycle") == 0)
135	    {
136	      count = apctl_u32(argc > 2 ? argv[2] : NULL, 3);
137	      timeout = apctl_u32(argc > 3 ? argv[3] : NULL,
138	                          BK7258_AP_DEFAULT_TIMEOUT_MS);
139	
140	      for (i = 0; i < count; i++)
141	        {
142	          ret = bk7258_ap_start(timeout);
143	          if (ret < 0)
144	            {
145	              break;
146	            }
147	
148	          apctl_status();
149	          ret = bk7258_ap_stop(timeout);
150	          if (ret < 0)
151	            {
152	              break;
153	            }
154	        }
155	    }
156	  else
157	    {
158	      apctl_usage();
159	      return 1;
160	    }
161	
162	  apctl_status();
163	  if (ret < 0)
164	    {
165	      fprintf(stderr, "apctl: %s failed: %d\n", argv[1], ret);
166	      return 1;
167	    }
168	
169	  return 0;
170	}
