1	/****************************************************************************
2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/ap/bk7258_ap_main.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * Minimal AP NuttX init task for physical CPU1.
7	 ****************************************************************************/
8	
9	/****************************************************************************
10	 * Included Files
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	
15	#include <stdint.h>
16	#include <string.h>
17	
18	#include <nuttx/kmalloc.h>
