23	#include "arm_internal.h"
24	#include "bk7258_clockdiag.h"
25	
26	/****************************************************************************
27	 * Pre-processor Definitions
28	 ****************************************************************************/
29	
30	#define BK7258_SCB_VTOR             (*(volatile uint32_t *)0xe000ed08u)
31	#define BK7258_SYSTICK_CTRL         (*(volatile uint32_t *)0xe000e010u)
32	#define BK7258_SYSTICK_RELOAD       (*(volatile uint32_t *)0xe000e014u)
33	#define BK7258_SYSTICK_CURRENT      (*(volatile uint32_t *)0xe000e018u)
34	#define BK7258_SYSTICK_ENABLE       (1u << 0)
35	#define BK7258_SYSTICK_TICKINT      (1u << 1)
36	#define BK7258_AP_HEARTBEAT_US      100000u
37	
38	/****************************************************************************
39	 * Private Functions
40	 ****************************************************************************/
41	
42	static inline volatile uint32_t *bk7258_ap_mbox(uint32_t base)
43	{
44	  return (volatile uint32_t *)(uintptr_t)base;
45	}
46	
47	static void bk7258_ap_mbox_ack(volatile uint32_t *mbox)
48	{
49	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
50	  __asm volatile ("dsb sy" ::: "memory");
51	  mbox[BK7258_MBOX_READY_OFFSET / 4] = 0;
52	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = 0;
53	  __asm volatile ("dsb sy" ::: "memory");
54	}
55	
56	static uint32_t bk7258_ap_mbox_receive(void)
57	{
58	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
59	  uint32_t event = BK7258_AP_EVENT_NONE;
60	
61	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
62	       BK7258_MBOX_BOX0_BIT) != 0)
63	    {
64	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
65	          BK7258_AP_DOORBELL_MAGIC)
66	        {
67	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
68	        }
69	
70	      bk7258_ap_mbox_ack(mbox);
71	    }
72	
73	  return event;
74	}
75	
76	static void bk7258_ap_mbox_send(uint32_t event)
77	{
78	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX1_BASE);
79	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
80	
81	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
82	       BK7258_MBOX_BOX0_BIT) != 0)
83	    {
84	      bk7258_ap_mbox_ack(mbox);
85	    }
86	
87	  mbox[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
88	  mbox[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
89	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
90	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
91	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
92	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->state;
93	  __asm volatile ("dmb sy" ::: "memory");
94	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
95	  state->ap_to_cp_doorbells++;
96	  __asm volatile ("dsb sy; sev" ::: "memory");
97	}
98	
99	static int bk7258_ap_validate_runtime(void)
100	{
101	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
102	  void *test;
103	  uint32_t msp;
104	
105	  __asm volatile ("mrs %0, msp" : "=r"(msp));
106	
107	  state->runtime_vtor    = BK7258_SCB_VTOR;
108	  state->runtime_msp     = msp;
109	  state->clock_hz        = bk7258_clockdiag_current_cpu_hz();
110	  state->systick_ctrl    = BK7258_SYSTICK_CTRL;
111	  state->systick_reload  = BK7258_SYSTICK_RELOAD;
112	  state->systick_current = BK7258_SYSTICK_CURRENT;
113	  state->heap_start      = (uint32_t)g_idle_topstack;
114	  state->heap_end        = BK7258_AP_HEAP_END;
115	  state->ram_start       = BK7258_AP_RAM_BASE;
116	  state->ram_end         = BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE;
117	  state->flash_start     = BK7258_AP_FLASH_ADDR;
118	  state->flash_end       = BK7258_AP_FLASH_ADDR + BK7258_AP_FLASH_SIZE;
119	
120	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR != 0 ||
121	      state->physical_core_id != 1)
122	    {
123	      return BK7258_AP_ERROR_BAD_CORE_ID;
124	    }
125	
126	  if (state->runtime_vtor < BK7258_AP_RAM_BASE ||
127	      state->runtime_vtor >= BK7258_SHARED_RAM_BASE ||
128	      (state->runtime_vtor & 0x1ffu) != 0)
129	    {
130	      return BK7258_AP_ERROR_BAD_VTOR;
131	    }
132	
133	  if ((state->systick_ctrl &
134	       (BK7258_SYSTICK_ENABLE | BK7258_SYSTICK_TICKINT)) !=
135	      (BK7258_SYSTICK_ENABLE | BK7258_SYSTICK_TICKINT) ||
136	      state->systick_reload == 0)
137	    {
138	      return BK7258_AP_ERROR_BAD_SYSTICK;
139	    }
140	
141	  test = kmm_malloc(64);
142	  if (test == NULL)
143	    {
144	      return BK7258_AP_ERROR_HEAP;
145	    }
146	
147	  memset(test, 0xa5, 64);
148	  state->heap_test = (uint32_t)(uintptr_t)test;
149	  kmm_free(test);
150	  return BK7258_AP_ERROR_NONE;
151	}
152	
153	/****************************************************************************
154	 * Public Functions
155	 ****************************************************************************/
156	
157	int bk7258_ap_main(int argc, char *argv[])
158	{
159	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
160	  uint32_t event;
161	  int error;
162	
163	  (void)argc;
164	  (void)argv;
165	
166	  if (state->magic != BK7258_AP_BOOT_STATE_MAGIC ||
167	      state->version != BK7258_AP_BOOT_STATE_VERSION ||
168	      state->size != sizeof(struct bk7258_ap_boot_state_s))
169	    {
170	      state->state = BK7258_AP_STATE_FAILED;
171	      state->error = BK7258_AP_ERROR_BAD_BOOT_STATE;
172	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
173	      goto parked;
174	    }
175	
176	  error = bk7258_ap_validate_runtime();
177	  if (error != BK7258_AP_ERROR_NONE)
178	    {
179	      state->state = BK7258_AP_STATE_FAILED;
180	      state->error = (uint32_t)error;
181	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
182	      goto parked;
183	    }
184	
185	  state->error      = BK7258_AP_ERROR_NONE;
186	  state->last_event = BK7258_AP_EVENT_READY;
187	  state->state      = BK7258_AP_STATE_READY;
188	  __asm volatile ("dmb sy" ::: "memory");
189	  bk7258_ap_mbox_send(BK7258_AP_EVENT_READY);
190	
191	  for (; ; )
192	    {
193	      event = bk7258_ap_mbox_receive();
194	      if (event != BK7258_AP_EVENT_NONE)
195	        {
196	          state->last_event = event;
197	        }
198	
199	      if (event == BK7258_AP_EVENT_STOP ||
200	          state->command == BK7258_AP_COMMAND_STOP)
201	        {
202	          state->state = BK7258_AP_STATE_STOPPING;
203	          __asm volatile ("dmb sy" ::: "memory");
204	          state->state = BK7258_AP_STATE_STOPPED;
205	          state->last_event = BK7258_AP_EVENT_STOPPED;
206	          bk7258_ap_mbox_send(BK7258_AP_EVENT_STOPPED);
207	          break;
208	        }
209	
210	      state->heartbeat++;
211	      nxsig_usleep(BK7258_AP_HEARTBEAT_US);
212	    }
213	
214	parked:
215	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
216	  for (; ; )
217	    {
218	      __asm volatile ("wfe");
219	    }
220	
221	  return 0;
222	}
