125	static void bk7258_ap_state_prepare(void)
126	{
127	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
128	  uint32_t generation = 1;
129	
130	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
131	      state->version == BK7258_AP_BOOT_STATE_VERSION)
132	    {
133	      generation = state->generation + 1;
134	    }
135	
136	  memset((void *)(uintptr_t)state, 0,
137	         sizeof(struct bk7258_ap_boot_state_s));
138	  bk7258_ap_fault_state()->magic = 0;
139	  state->magic       = BK7258_AP_BOOT_STATE_MAGIC;
140	  state->version     = BK7258_AP_BOOT_STATE_VERSION;
141	  state->size        = sizeof(struct bk7258_ap_boot_state_s);
142	  state->generation  = generation;
143	  state->command     = BK7258_AP_COMMAND_START;
144	  state->state       = BK7258_AP_STATE_STARTING;
145	  state->ram_start   = BK7258_AP_RAM_BASE;
146	  state->ram_end     = BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE;
147	  state->flash_start = BK7258_AP_FLASH_ADDR;
148	  state->flash_end   = BK7258_AP_FLASH_ADDR + BK7258_AP_FLASH_SIZE;
149	  __asm volatile ("dmb sy" ::: "memory");
150	}
151	
152	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
153	{
154	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
155	  uint32_t elapsed;
156	  uint32_t event;
157	
158	  if (timeout_ms == 0)
159	    {
160	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
161	    }
162	
163	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
164	    {
165	      event = bk7258_ap_mbox_receive();
166	      if (event != BK7258_AP_EVENT_NONE)
167	        {
168	          state->last_event = event;
169	        }
170	
171	      __asm volatile ("dmb sy" ::: "memory");
172	      if (state->state == wanted)
173	        {
174	          return OK;
175	        }
176	
177	      if (state->state == BK7258_AP_STATE_FAILED)
178	        {
179	          return -EIO;
180	        }
181	
182	      nxsig_usleep(1000);
183	    }
184	
185	  return -ETIMEDOUT;
186	}
187	
188	static int bk7258_ap_start_locked(uint32_t timeout_ms)
189	{
190	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
191	  int ret;
192	
193	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
194	      (state->state == BK7258_AP_STATE_READY ||
195	       state->state == BK7258_AP_STATE_STARTING))
196	    {
197	      return -EBUSY;
198	    }
199	
200	  /* Hold CPU1 while replacing shared state and the boot address. */
201	
202	  sys_drv_set_cpu1_reset(0);
203	  bk7258_ap_mbox_initialize();
204	  bk7258_ap_state_prepare();
205	
206	  /* Exact BK7258 CPU1 release order from the CP SDK. */
207	
208	  sys_drv_set_cpu1_pwr_dw(0);
209	  sys_drv_set_cpu1_rxevt_sel(1);
210	  sys_drv_set_cpu1_boot_address_offset(BK7258_AP_FLASH_ADDR >> 8);
211	  __asm volatile ("dsb sy; isb sy" ::: "memory");
212	  sys_drv_set_cpu1_reset(1);
213	  __asm volatile ("dsb sy; sev" ::: "memory");
214	
215	  ret = bk7258_ap_wait(BK7258_AP_STATE_READY, timeout_ms);
216	  if (ret < 0)
217	    {
218	      sys_drv_set_cpu1_reset(0);
219	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
220	      sys_drv_set_cpu1_pwr_dw(1);
221	
222	      if (state->state != BK7258_AP_STATE_FAILED)
223	        {
224	          state->error = BK7258_AP_ERROR_TIMEOUT;
225	        }
226	
227	      state->command = BK7258_AP_COMMAND_NONE;
228	      state->state = BK7258_AP_STATE_FAILED;
229	      state->last_event = BK7258_AP_EVENT_FAILED;
230	      __asm volatile ("dmb sy" ::: "memory");
231	    }
232	
233	  return ret;
234	}
235	
236	static int bk7258_ap_stop_locked(uint32_t timeout_ms)
237	{
238	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
239	  int ret = OK;
240	
241	  if (state->state == BK7258_AP_STATE_READY ||
242	      state->state == BK7258_AP_STATE_STARTING)
243	    {
244	      state->command = BK7258_AP_COMMAND_STOP;
245	      __asm volatile ("dmb sy" ::: "memory");
246	      bk7258_ap_mbox_send(BK7258_AP_EVENT_STOP);
247	      ret = bk7258_ap_wait(BK7258_AP_STATE_STOPPED, timeout_ms);
248	    }
