67	{
68	  volatile uint32_t *to_ap = bk7258_ap_mbox(BK7258_MBOX0_BASE);
69	  volatile uint32_t *to_cp = bk7258_ap_mbox(BK7258_MBOX1_BASE);
70	
71	  to_ap[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
72	  to_cp[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
73	  to_ap[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 0;
74	  to_ap[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 1;
75	  to_cp[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
76	  to_cp[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
77	
78	  bk7258_ap_mbox_ack(to_ap);
79	  bk7258_ap_mbox_ack(to_cp);
80	}
