82	static void bk7258_ap_mbox_send(uint32_t event)
83	{
84	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
85	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
86	
87	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
88	       BK7258_MBOX_BOX0_BIT) != 0)
89	    {
90	      bk7258_ap_mbox_ack(mbox);
91	    }
