93	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
94	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
95	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
96	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->command;
97	  __asm volatile ("dmb sy" ::: "memory");
98	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
99	  state->cp_to_ap_doorbells++;
