153	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
154	{
155	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
156	  uint32_t elapsed;
157	  uint32_t event;
158	
159	  if (timeout_ms == 0)
160	    {
161	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
162	    }
163	
164	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
165	    {
166	      event = bk7258_ap_mbox_receive();
167	      if (event != BK7258_AP_EVENT_NONE)
168	        {
169	          state->last_event = event;
170	        }
171	
172	      __asm volatile ("dmb sy" ::: "memory");
173	      if (state->state == wanted)
174	        {
175	          return OK;
176	        }
177	
178	      if (state->state == BK7258_AP_STATE_FAILED)
179	        {
180	          return -EIO;
181	        }
182	
183	      nxsig_usleep(1000);
184	    }
185	
186	  return -ETIMEDOUT;
187	}
