210	  sys_drv_set_cpu1_rxevt_sel(1);
211	  sys_drv_set_cpu1_boot_address_offset(BK7258_AP_FLASH_ADDR >> 8);
212	  __asm volatile ("dsb sy; isb sy" ::: "memory");
213	  sys_drv_set_cpu1_reset(1);
214	  __asm volatile ("dsb sy; sev" ::: "memory");
215	
216	  ret = bk7258_ap_wait(BK7258_AP_STATE_READY, timeout_ms);
217	  if (ret < 0)
218	    {
219	      sys_drv_set_cpu1_reset(0);
220	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
221	      sys_drv_set_cpu1_pwr_dw(1);
222	
223	      if (state->state != BK7258_AP_STATE_FAILED)
224	        {
225	          state->error = BK7258_AP_ERROR_TIMEOUT;
226	        }
227	
228	      state->command = BK7258_AP_COMMAND_NONE;
229	      state->state = BK7258_AP_STATE_FAILED;
230	      state->last_event = BK7258_AP_EVENT_FAILED;
231	      __asm volatile ("dmb sy" ::: "memory");
232	    }
233	
234	  return ret;
235	}
